   ("Donner un avis", {"study":"Creo que {s}.","phon":"KRÉ-o ké {s}","native":"Je crois que {s}."},
    [S("es una buena idea","és OU-na BOUÉ-na i-DÉ-a","c'est une bonne idée"), S("el restaurante está cerrado","él rrés-taou-RAN-té és-TA ssé-RRA-do","le restaurant est fermé"), S("tienes razón","TIÉ-nés rra-SSON","tu as raison"), S("va a llover","ba a yo-BÉR","il va pleuvoir")]),
